--!strict
-- InventorySync — Client-server inventory replication
local ReplicatedStorage = game:GetService("ReplicatedStorage")
export type InventorySnapshot = { [string]: number }
export type InventorySync = {
    SyncToClient: (self: InventorySync, player: Player, snapshot: InventorySnapshot) -> (),
    RequestSync: (self: InventorySync, player: Player) -> (),
    Destroy: (self: InventorySync) -> (),
}
type Internal = InventorySync & { _remote: RemoteEvent, _conns: {RBXScriptConnection} }
local Impl = {}; Impl.__index = Impl
function Impl.SyncToClient(self: Internal, player: Player, snapshot: InventorySnapshot)
    self._remote:FireClient(player, snapshot)
end
function Impl.RequestSync(self: Internal, player: Player)
    -- Server should listen for this and respond with current inventory
end
function Impl.Destroy(self: Internal)
    for _, c in self._conns do c:Disconnect() end; table.clear(self._conns)
end
local InventorySync = {}
function InventorySync.new(): InventorySync
    local folder = Instance.new("Folder"); folder.Name = "InventoryRemotes"; folder.Parent = ReplicatedStorage
    local remote = Instance.new("RemoteEvent"); remote.Name = "InventoryUpdate"; remote.Parent = folder
    return setmetatable({ _remote = remote, _conns = {} }, Impl) :: any
end
return InventorySync

